  1	//! Learned solver selector using a small MLP in Candle.
  2	//!
  3	//! Replaces the rule-based `predict_solver` in `ml_legacy.rs`.
  4	//!
  5	//! Architecture: 28 → 128 → 64 → 5  (input → hidden → hidden → num_solvers)
  6	//! Activation: ReLU hidden, Softmax output.
  7	//!
  8	//! Weights are loaded from a safetensors file at runtime.
  9	//! If the model file is missing, falls back to the rule-based selector.
 10	
 11	use crate::core::ml::features::InstanceFeatures;
 12	use crate::core::ml_legacy::predict_solver as rule_predict_solver;
 13	use crate::core::vrp::types::VRPSolverInput;
 14	use anyhow::{Context, Result};
 15	use candle_core::{Device, Tensor, DType};
 16	use candle_nn::{linear, Module, VarBuilder, Linear};
 17	use serde::{Deserialize, Serialize};
 18	use std::path::Path;
 19	
 20	const NUM_FEATURES: usize = 28;
 21	const HIDDEN1: usize = 128;
 22	const HIDDEN2: usize = 64;
 23	const NUM_SOLVERS: usize = 6;
 24	
 25	const SOLVER_IDS: [&str; NUM_SOLVERS] = [
 26	    "default",
 27	    "clarke_wright",
 28	    "sweep",
 29	    "or_opt",
 30	    "two_opt",
 31	    "neural_guided",
 32	];
 33	
 34	/// Learned MLP solver selector.
 35	pub struct NeuralSelector {
 36	    lin1: Linear,
 37	    lin2: Linear,
 38	    lin3: Linear,
 39	    device: Device,
 40	}
 41	
 42	impl NeuralSelector {
 43	    /// Load from a safetensors file.
 44	    pub fn from_file(path: &Path) -> Result<Self> {
 45	        let device = crate::core::ml::best_device()?;
 46	        let tensors = candle_core::safetensors::load(path, &device)
 47	            .with_context(|| format!("Failed to load safetensors from {}", path.display()))?;
 48	        let vb = VarBuilder::from_tensors(tensors, DType::F32, &device);
 49	        let lin1 = linear(NUM_FEATURES, HIDDEN1, vb.pp("lin1"))?;
 50	        let lin2 = linear(HIDDEN1, HIDDEN2, vb.pp("lin2"))?;
 51	        let lin3 = linear(HIDDEN2, NUM_SOLVERS, vb.pp("lin3"))?;
 52	        Ok(Self { lin1, lin2, lin3, device })
 53	    }
 54	
 55	    /// Predict best solver using classification (argmax probability).
 56	    pub fn predict(&self,
 57	        features: &InstanceFeatures,
 58	    ) -> Result<NeuralPrediction> {
 59	        let x = features.to_vector();
 60	        let input = Tensor::from_vec(x, (1, NUM_FEATURES), &self.device)?;
 61	        let h1 = self.lin1.forward(&input)?.relu()?;
 62	        let h2 = self.lin2.forward(&h1)?.relu()?;
 63	        let logits = self.lin3.forward(&h2)?;
 64	        let probs = candle_nn::ops::softmax(&logits, 1)?;
 65	        let vals: Vec<f32> = probs.squeeze(0)?.to_vec1()?;
 66	        
 67	        let mut indexed: Vec<(usize, f32)> = vals.iter().enumerate().map(|(i, &v)| (i, v)).collect();
 68	        // Sort by probability DESCENDING (higher is better)
 69	        indexed.sort_by(|a, b| b.1.partial_cmp(&a.1).unwrap_or(std::cmp::Ordering::Equal));
 70	
 71	        let best_idx = indexed[0].0;
 72	        let best_prob = indexed[0].1;
 73	        let runner_up = indexed.get(1).map(|(i, v)| (SOLVER_IDS[*i].to_string(), *v));
 74	
 75	        let all_scores: Vec<(String, f64)> = indexed
 76	            .iter()
 77	            .map(|(i, v)| (SOLVER_IDS[*i].to_string(), *v as f64))
 78	            .collect();
 79	
 80	        Ok(NeuralPrediction {
 81	            recommended: SOLVER_IDS[best_idx].to_string(),
 82	            confidence: best_prob as f64,
 83	            runner_up,
 84	            all_scores,
 85	        })
 86	    }
 87	}
 88	
 89	/// Prediction result from the neural selector.
 90	#[derive(Debug, Clone, Serialize, Deserialize)]
 91	pub struct NeuralPrediction {
 92	    pub recommended: String,
 93	    pub confidence: f64,
 94	    pub runner_up: Option<(String, f32)>,
 95	    pub all_scores: Vec<(String, f64)>,
 96	}
 97	
 98	/// High-level API: predict the best solver for a VRP instance.
 99	///
100	/// Tries to load the neural model from `model_path`. If missing or failed,
101	/// falls back to the legacy rule-based selector.
102	pub fn predict_solver(
103	    input: &VRPSolverInput,
104	    model_path: Option<&Path>,
105	) -> Result<NeuralPrediction> {
106	    let features = InstanceFeatures::from_input(input);
107	
108	    if let Some(path) = model_path {
109	        if path.exists() {
110	            match NeuralSelector::from_file(path) {
111	                Ok(selector) => {
112	                    match selector.predict(&features) {
113	                        Ok(pred) => return Ok(pred),
114	                        Err(e) => {
115	                            println!("DEBUG: Neural selector inference failed: {}", e);
116	                            tracing::warn!("Neural selector inference failed: {}. Falling back to rule-based.", e);
117	                        }
118	                    }
119	                }
120	                Err(e) => {
121	                    println!("DEBUG: Failed to load neural selector from {:?}: {}", path, e);
122	                    tracing::warn!("Failed to load neural selector: {}. Falling back to rule-based.", e);
123	                }
124	            }
125	        } else {
126	            println!("DEBUG: model_path {:?} does not exist", path);
127	        }
128	    }
129	
130	    // Fallback: rule-based
131	    let legacy = rule_predict_solver(&crate::core::ml_legacy::RouteFeatures::from_input(input)
132	    );
133	    let all_scores: Vec<(String, f64)> = legacy.all_scores;
134	    let runner_up = legacy.runner_up.map(|(id, score)| (id, score as f32));
135	    Ok(NeuralPrediction {
136	        recommended: legacy.recommended,
137	        confidence: legacy.confidence,
138	        runner_up,
139	        all_scores,
140	    })
141	}
142	
143	/// Default model path relative to the executable.
144	pub fn default_model_path() -> std::path::PathBuf {
145	    // 1. Try relative to current executable
146	    if let Ok(exe_path) = std::env::current_exe() {
147	        if let Some(exe_dir) = exe_path.parent() {
148	            let p = exe_dir.join("models").join("solver_selector.safetensors");
149	            if p.exists() {
150	                return p;
151	            }
152	        }
153	    }
154	
155	    // 2. Try relative to current working directory
156	    let p = std::path::PathBuf::from("models/solver_selector.safetensors");
157	    if p.exists() {
158	        return p;
159	    }
160	
161	    // Fallback
162	    std::env::current_exe()
163	        .unwrap_or_else(|_| std::path::PathBuf::from("."))
164	        .parent()
165	        .unwrap_or(std::path::Path::new("."))
166	        .join("models")
167	        .join("solver_selector.safetensors")
168	}
169	
170	#[cfg(test)]
171	mod tests {
172	    use super::*;
173	    use crate::core::vrp::test_utils::{make_input, make_stop};
174	
175	    #[test]
176	    fn test_neural_selector_shape() {
177	        let stops = vec![
178	            make_stop(0.0, 0.0, "depot"),
179	            make_stop(1.0, 0.0, "a"),
180	            make_stop(0.0, 1.0, "b"),
181	        ];
182	        let input = make_input(stops, 1);
183	        let features = InstanceFeatures::from_input(&input);
184	        let vec = features.to_vector();
185	        assert_eq!(vec.len(), NUM_FEATURES);
186	    }
187	
188	    #[test]
189	    fn test_predict_solver_fallback() {
190	        let stops = vec![
191	            make_stop(0.0, 0.0, "depot"),
192	            make_stop(1.0, 0.0, "a"),
193	            make_stop(2.0, 0.0, "b"),
194	        ];
195	        let input = make_input(stops, 1);
196	        let pred = predict_solver(&input, Some(Path::new("/nonexistent/model.safetensors"))
197	        ).unwrap();
198	        assert!(!pred.recommended.is_empty());
199	        assert!(pred.confidence > 0.0);
200	    }
201	}

  1	//! Evaluate the trained neural solver selector against a held-out test set.
  2	//!
  3	//! Generates N new synthetic instances (not seen during training),
  4	//! predicts the best solver using the neural selector, runs that solver,
  5	//! and compares the achieved distance vs. always-default and always-or_opt.
  6	//!
  7	//! Usage: cargo run --bin evaluate-selector --features ml --release -- 200
  8	
  9	use tokio::runtime::Runtime;
 10	
 11	use v2rmp::core::ml::features::InstanceFeatures;
 12	use v2rmp::core::ml::selector::{predict_solver, NeuralPrediction};
 13	use v2rmp::core::vrp::registry::{get_solver_list, solve_with};
 14	use v2rmp::core::vrp::types::{VRPSolverInput, VRPSolverStop, VrpObjective};
 15	use v2rmp::core::vrp::utils::build_haversine_matrix;
 16	use std::collections::hash_map::DefaultHasher;
 17	use std::hash::{Hash, Hasher};
 18	
 19	struct FastPrng(u64);
 20	
 21	fn fast_prng(seed: u64) -> FastPrng {
 22	    FastPrng(seed.wrapping_mul(6364136223846793005).wrapping_add(1))
 23	}
 24	
 25	impl FastPrng {
 26	    fn next(&mut self) -> u64 {
 27	        self.0 = self.0.wrapping_mul(6364136223846793005).wrapping_add(1);
 28	        self.0
 29	    }
 30	    fn unit(&mut self) -> f64 {
 31	        ((self.next() >> 11) as f64) / ((1u64 << 53) as f64)
 32	    }
 33	    fn range(&mut self, lo: usize, hi: usize) -> usize {
 34	        if lo >= hi { return lo; }
 35	        lo + (self.next() as usize % (hi - lo))
 36	    }
 37	}
 38	
 39	fn generate_instance(seed_offset: usize) -> Vec<VRPSolverStop> {
 40	    let mut hasher = DefaultHasher::new();
 41	    // Different seed range than training to avoid overlap
 42	    (seed_offset + 100_000).hash(&mut hasher);
 43	    let seed = hasher.finish();
 44	    let mut rng = fast_prng(seed);
 45	
 46	    let pattern = seed_offset % 4;
 47	    let n_stops = rng.range(15, 120);
 48	
 49	    let depot_lat = 45.3 + rng.unit() * 0.8;
 50	    let depot_lon = -74.0 + rng.unit() * 0.8;
 51	
 52	    let mut stops = vec![VRPSolverStop {
 53	        lat: depot_lat,
 54	        lon: depot_lon,
 55	        label: "depot".to_string(),
 56	        demand: Some(0.0),
 57	        arrival_time: None,
 58	    }];
 59	
 60	    for i in 1..=n_stops {
 61	        let (lat, lon) = match pattern {
 62	            0 => {
 63	                let lat = depot_lat + (rng.unit() - 0.5) * 2.0;
 64	                let lon = depot_lon + (rng.unit() - 0.5) * 2.0;
 65	                (lat, lon)
 66	            }
 67	            1 => {
 68	                let cx = depot_lat + (rng.unit() - 0.5) * 1.5;
 69	                let cy = depot_lon + (rng.unit() - 0.5) * 1.5;
 70	                let lat = cx + (rng.unit() - 0.5) * 0.3;
 71	                let lon = cy + (rng.unit() - 0.5) * 0.3;
 72	                (lat, lon)
 73	            }
 74	            2 => {
 75	                let grid_n = ((n_stops as f64).sqrt().ceil() as f64).max(2.0);
 76	                let gx = (i as f64 % grid_n) / grid_n;
 77	                let gy = (i as f64 / grid_n) / grid_n;
 78	                let lat = depot_lat + (gx - 0.5) * 1.5 + (rng.unit() - 0.5) * 0.05;
 79	                let lon = depot_lon + (gy - 0.5) * 1.5 + (rng.unit() - 0.5) * 0.05;
 80	                (lat, lon)
 81	            }
 82	            _ => {
 83	                let angle = rng.unit() * std::f64::consts::PI * 2.0;
 84	                let radius = rng.unit() * 0.8;
 85	                let lat = depot_lat + radius * angle.sin();
 86	                let lon = depot_lon + radius * angle.cos();
 87	                (lat, lon)
 88	            }
 89	        };
 90	
 91	        stops.push(VRPSolverStop {
 92	            lat,
 93	            lon,
 94	            label: format!("stop_{}", i),
 95	            demand: Some(rng.range(1, 20) as f64),
 96	            arrival_time: None,
 97	        });
 98	    }
 99	
100	    stops
101	}
102	
103	fn make_input(stops: Vec<VRPSolverStop>, num_vehicles: usize, objective: VrpObjective) -> VRPSolverInput {
104	    let matrix = build_haversine_matrix(&stops, 40.0);
105	    VRPSolverInput {
106	        locations: stops,
107	        num_vehicles,
108	        vehicle_capacity: 100.0,
109	        objective,
110	        matrix: Some(matrix),
111	        service_time_secs: None,
112	        use_time_windows: false,
113	        window_open: None,
114	        window_close: None,
115	        hyperparams: None,
116	    }
117	}
118	
119	fn objective_from_idx(idx: usize) -> VrpObjective {
120	    match idx % 4 {
121	        0 => VrpObjective::MinDistance,
122	        1 => VrpObjective::MinTime,
123	        2 => VrpObjective::BalanceLoad,
124	        _ => VrpObjective::MinVehicles,
125	    }
126	}
127	
128	fn main() {
129	    let n_test: usize = std::env::args()
130	        .nth(1)
131	        .and_then(|s| s.parse().ok())
132	        .unwrap_or(200);
133	
134	    let rt = Runtime::new().expect("Tokio runtime");
135	    let solver_ids = get_solver_list();
136	
137	    println!("Evaluating neural solver selector on {} held-out instances...", n_test);
138	    println!("Solver IDs: {:?}", solver_ids);
139	    println!();
140	
141	    let mut neural_wins = 0usize;
142	    let mut default_wins = 0usize;
143	    let mut or_opt_wins = 0usize;
144	    let oracle_wins = 0usize;
145	
146	    let mut neural_total_dist = 0.0f64;
147	    let mut default_total_dist = 0.0f64;
148	    let mut or_opt_total_dist = 0.0f64;
149	    let mut oracle_total_dist = 0.0f64;
150	
151	    let mut selector_correct = 0usize;
152	    let mut selector_top2 = 0usize;
153	
154	    for i in 0..n_test {
155	        let stops = generate_instance(i);
156	        let n_vehicles = fast_prng((i + 100_000) as u64).range(1, 11).max(1);
157	        let objective = objective_from_idx(i + 100);
158	        let input = make_input(stops.clone(), n_vehicles, objective.clone());
159	
160	        // Neural prediction
161	        let pred = predict_solver(&input, None).unwrap_or(NeuralPrediction {
162	            recommended: "default".to_string(),
163	            confidence: 0.0,
164	            runner_up: None,
165	            all_scores: vec![],
166	        });
167	
168	        // Run all solvers
169	        let mut best_solver = String::new();
170	        let mut best_dist = f64::INFINITY;
171	        let mut predicted_dist = f64::INFINITY;
172	        let mut default_dist = f64::INFINITY;
173	        let mut or_opt_dist_val = f64::INFINITY;
174	
175	        for solver_id in &solver_ids {
176	            let input_clone = VRPSolverInput {
177	                locations: input.locations.clone(),
178	                num_vehicles: input.num_vehicles,
179	                vehicle_capacity: input.vehicle_capacity,
180	                objective: input.objective.clone(),
181	                matrix: input.matrix.clone(),
182	                service_time_secs: input.service_time_secs,
183	                use_time_windows: input.use_time_windows,
184	                window_open: input.window_open,
185	                window_close: input.window_close,
186	                hyperparams: input.hyperparams.clone(),
187	            };
188	
189	            let result = rt.block_on(async {
190	                solve_with(solver_id, &input_clone).await
191	            });
192	
193	            let dist = match result {
194	                Ok(output) => output.total_distance_km.parse().unwrap_or(f64::MAX),
195	                Err(_) => f64::MAX,
196	            };
197	
198	            if dist < best_dist {
199	                best_dist = dist;
200	                best_solver = solver_id.clone();
201	            }
202	            if solver_id == &pred.recommended {
203	                predicted_dist = dist;
204	            }
205	            if solver_id == "default" {
206	                default_dist = dist;
207	            }
208	            if solver_id == "or_opt" {
209	                or_opt_dist_val = dist;
210	            }
211	        }
212	
213	        // Track selector correctness
214	        if pred.recommended == best_solver {
215	            selector_correct += 1;
216	        }
217	        if let Some((runner_id, _)) = &pred.runner_up {
218	            if pred.recommended == best_solver || runner_id == &best_solver {
219	                selector_top2 += 1;
220	            }
221	        }
222	
223	        // Track which strategy "wins" this instance
224	        if predicted_dist == best_dist {
225	            neural_wins += 1;
226	        }
227	        if default_dist == best_dist {
228	            default_wins += 1;
229	        }
230	        if or_opt_dist_val == best_dist {
231	            or_opt_wins += 1;
232	        }
233	        oracle_total_dist += best_dist;
234	
235	        neural_total_dist += predicted_dist.min(best_dist * 2.0); // avoid inf explosion
236	        default_total_dist += default_dist;
237	        or_opt_total_dist += or_opt_dist_val;
238	    }
239	
240	    println!("========================================");
241	    println!("HELD-OUT EVALUATION RESULTS (n={})", n_test);
242	    println!("========================================");
243	    println!();
244	    println!("--- Selector Accuracy ---");
245	    println!("  Top-1 accuracy:  {}/{} ({:.1}%)", selector_correct, n_test, selector_correct as f64 / n_test as f64 * 100.0);
246	    println!("  Top-2 accuracy:  {}/{} ({:.1}%)", selector_top2, n_test, selector_top2 as f64 / n_test as f64 * 100.0);
247	    println!();
248	    println!("--- Best-Solver Distribution ---");
249	    println!("  Neural (predicted): {}/{} ({:.1}%)", neural_wins, n_test, neural_wins as f64 / n_test as f64 * 100.0);
250	    println!("  Always-default:     {}/{} ({:.1}%)", default_wins, n_test, default_wins as f64 / n_test as f64 * 100.0);
251	    println!("  Always-or_opt:      {}/{} ({:.1}%)", or_opt_wins, n_test, or_opt_wins as f64 / n_test as f64 * 100.0);
252	    println!();
253	    println!("--- Total Distance (lower is better) ---");
254	    println!("  Neural predicted:   {:.2} km", neural_total_dist);
255	    println!("  Always-default:     {:.2} km", default_total_dist);
256	    println!("  Always-or_opt:      {:.2} km", or_opt_total_dist);
257	    println!("  Oracle (best):      {:.2} km", oracle_total_dist);
258	    println!();
259	    println!("--- Gap to Oracle ---");
260	    println!("  Neural:    {:.2}%", (neural_total_dist - oracle_total_dist) / oracle_total_dist * 100.0);
261	    println!("  Default:   {:.2}%", (default_total_dist - oracle_total_dist) / oracle_total_dist * 100.0);
262	    println!("  Or-Opt:    {:.2}%", (or_opt_total_dist - oracle_total_dist) / oracle_total_dist * 100.0);
263	}

  1	//! Training data generator for ML models.
  2	//!
  3	//! Generates synthetic VRP instances, runs all 5 solvers, and records:
  4	//! - instance features (28-dim)
  5	//! - best solver id
  6	//! - best achieved distance
  7	//! - gap to a star-tour lower bound (heuristic)
  8	//! - per-solver distances
  9	//!
 10	//! Usage: cargo run --bin generate-training-data --release > training_data.jsonl
 11	
 12	use std::sync::Arc;
 13	use tokio::runtime::Runtime;
 14	
 15	use v2rmp::core::haversine_m;
 16	use v2rmp::core::ml::features::InstanceFeatures;
 17	use v2rmp::core::vrp::registry::{get_solver_list, solve_with};
 18	use v2rmp::core::vrp::types::{VRPSolverInput, VRPSolverStop, VrpObjective, SolverHyperparams};
 19	use v2rmp::core::vrp::utils::build_haversine_matrix;
 20	
 21	/// Generate a single synthetic VRP instance with depot at index 0.
 22	fn generate_instance(seed_offset: usize) -> Vec<VRPSolverStop> {
 23	    use std::collections::hash_map::DefaultHasher;
 24	    use std::hash::{Hash, Hasher};
 25	
 26	    let mut hasher = DefaultHasher::new();
 27	    seed_offset.hash(&mut hasher);
 28	    let seed = hasher.finish();
 29	    let mut rng = fast_prng(seed);
 30	
 31	    let pattern = seed_offset % 4;
 32	    let n_stops = match seed_offset % 10 {
 33	        0 | 1 => rng.range(10, 25),
 34	        2 | 3 | 4 => rng.range(20, 60),
 35	        5 | 6 | 7 => rng.range(50, 150),
 36	        _ => rng.range(100, 250),
 37	    };
 38	
 39	    // Base depot near Montreal or random
 40	    let depot_lat = 45.5 + rng.unit() * 0.5;
 41	    let depot_lon = -73.7 + rng.unit() * 0.5;
 42	
 43	    let mut stops: Vec<VRPSolverStop> = vec![VRPSolverStop {
 44	        lat: depot_lat,
 45	        lon: depot_lon,
 46	        label: "depot".to_string(),
 47	        demand: Some(0.0),
 48	        arrival_time: None,
 49	    }];
 50	
 51	    for i in 1..=n_stops {
 52	        let (lat, lon) = match pattern {
 53	            0 => {
 54	                // Random uniform around depot
 55	                let lat = depot_lat + (rng.unit() - 0.5) * 2.0;
 56	                let lon = depot_lon + (rng.unit() - 0.5) * 2.0;
 57	                (lat, lon)
 58	            }
 59	            1 => {
 60	                // Clustered around 2-4 centres
 61	                let num_clusters = rng.range(2, 5) as usize;
 62	                let cx = depot_lat + (rng.unit() - 0.5) * 1.5;
 63	                let cy = depot_lon + (rng.unit() - 0.5) * 1.5;
 64	                let lat = cx + (rng.unit() - 0.5) * 0.3;
 65	                let lon = cy + (rng.unit() - 0.5) * 0.3;
 66	                (lat, lon)
 67	            }
 68	            2 => {
 69	                // Grid-like
 70	                let grid_n = ((n_stops as f64).sqrt().ceil() as f64).max(2.0);
 71	                let gx = (i as f64 % grid_n) / grid_n;
 72	                let gy = (i as f64 / grid_n) / grid_n;
 73	                let lat = depot_lat + (gx - 0.5) * 1.5 + (rng.unit() - 0.5) * 0.05;
 74	                let lon = depot_lon + (gy - 0.5) * 1.5 + (rng.unit() - 0.5) * 0.05;
 75	                (lat, lon)
 76	            }
 77	            _ => {
 78	                // Radial
 79	                let angle = rng.unit() * std::f64::consts::PI * 2.0;
 80	                let radius = rng.unit() * 0.8;
 81	                let lat = depot_lat + radius * angle.sin();
 82	                let lon = depot_lon + radius * angle.cos();
 83	                (lat, lon)
 84	            }
 85	        };
 86	
 87	        stops.push(VRPSolverStop {
 88	            lat,
 89	            lon,
 90	            label: format!("stop_{}", i),
 91	            demand: Some(rng.range(1, 20) as f64),
 92	            arrival_time: None,
 93	        });
 94	    }
 95	
 96	    stops
 97	}
 98	
 99	/// Simple deterministic PRNG.
100	struct FastPrng(u64);
101	
102	fn fast_prng(seed: u64) -> FastPrng {
103	    FastPrng(seed.wrapping_mul(6364136223846793005).wrapping_add(1))
104	}
105	
106	impl FastPrng {
107	    fn next(&mut self) -> u64 {
108	        self.0 = self.0.wrapping_mul(6364136223846793005).wrapping_add(1);
109	        self.0
110	    }
111	
112	    fn unit(&mut self) -> f64 {
113	        ((self.next() >> 11) as f64) / ((1u64 << 53) as f64)
114	    }
115	
116	    fn range(&mut self, lo: usize, hi: usize) -> usize {
117	        if lo >= hi {
118	            return lo;
119	        }
120	        lo + (self.next() as usize % (hi - lo))
121	    }
122	}
123	
124	/// Lower bound: sum of depot→stop distances × 2 (out-and-back star tour).
125	fn star_tour_lower_bound(locations: &[VRPSolverStop]) -> f64 {
126	    let depot = &locations[0];
127	    let mut total = 0.0;
128	    for s in &locations[1..] {
129	        total += haversine_m(depot.lat, depot.lon, s.lat, s.lon) / 1000.0;
130	    }
131	    total * 2.0
132	}
133	
134	fn make_input(stops: Vec<VRPSolverStop>, num_vehicles: usize, objective: VrpObjective) -> VRPSolverInput {
135	    let matrix = build_haversine_matrix(&stops, 40.0);
136	    VRPSolverInput {
137	        locations: stops,
138	        num_vehicles,
139	        vehicle_capacity: 100.0,
140	        objective,
141	        matrix: Some(matrix),
142	        service_time_secs: None,
143	        use_time_windows: false,
144	        window_open: None,
145	        window_close: None,
146	        hyperparams: None,
147	    }
148	}
149	
150	fn objective_from_idx(idx: usize) -> VrpObjective {
151	    match idx % 4 {
152	        0 => VrpObjective::MinDistance,
153	        1 => VrpObjective::MinTime,
154	        2 => VrpObjective::BalanceLoad,
155	        _ => VrpObjective::MinVehicles,
156	    }
157	}
158	
159	fn main() {
160	    let n_instances: usize = std::env::args()
161	        .nth(1)
162	        .and_then(|s| s.parse().ok())
163	        .unwrap_or(1000);
164	
165	    let rt = Runtime::new().expect("Failed to create Tokio runtime");
166	    let solver_ids = get_solver_list();
167	
168	    eprintln!("Generating {} synthetic VRP instances and evaluating {} solvers...", n_instances, solver_ids.len());
169	
170	    for i in 0..n_instances {
171	        let stops = generate_instance(i);
172	        let n_vehicles = fast_prng(i as u64 * 7).range(1, 11).max(1);
173	        let objective = objective_from_idx(i);
174	        let input = make_input(stops.clone(), n_vehicles, objective.clone());
175	
176	        let features = InstanceFeatures::from_input(&input);
177	        let feature_vec = features.to_vector();
178	
179	        let mut best_dist = f64::INFINITY;
180	        let mut best_solver = String::new();
181	        let mut solver_dists: Vec<(String, f64)> = Vec::new();
182	
183	        for solver_id in &solver_ids {
184	            let input_clone = VRPSolverInput {
185	                locations: input.locations.clone(),
186	                num_vehicles: input.num_vehicles,
187	                vehicle_capacity: input.vehicle_capacity,
188	                objective: input.objective.clone(),
189	                matrix: input.matrix.clone(),
190	                service_time_secs: input.service_time_secs,
191	                use_time_windows: input.use_time_windows,
192	                window_open: input.window_open,
193	                window_close: input.window_close,
194	                hyperparams: input.hyperparams.clone(),
195	            };
196	
197	            let result = rt.block_on(async {
198	                solve_with(solver_id, &input_clone).await
199	            });
200	
201	            match result {
202	                Ok(output) => {
203	                    let dist: f64 = output.total_distance_km.parse().unwrap_or(f64::MAX);
204	                    solver_dists.push((solver_id.clone(), dist));
205	                    if dist < best_dist {
206	                        best_dist = dist;
207	                        best_solver = solver_id.clone();
208	                    }
209	                }
210	                Err(e) => {
211	                    eprintln!("  Solver {} failed for instance {}: {}", solver_id, i, e);
212	                }
213	            }
214	        }
215	
216	        let lower = star_tour_lower_bound(&input.locations);
217	        let gap = if lower > 0.0 {
218	            ((best_dist - lower) / lower * 100.0).clamp(0.0, 100.0)
219	        } else {
220	            0.0
221	        };
222	
223	        let record = serde_json::json!({
224	            "features": feature_vec,
225	            "best_solver": best_solver,
226	            "best_distance_km": best_dist,
227	            "lower_bound_km": lower,
228	            "gap_pct": gap,
229	            "n_stops": input.locations.len().saturating_sub(1),
230	            "n_vehicles": input.num_vehicles,
231	            "objective": format!("{:?}", objective),
232	            "solver_dists": solver_dists.into_iter().map(|(id, d)| serde_json::json!({"solver": id, "distance": d})).collect::<Vec<_>>(),
233	        });
234	
235	        println!("{}", record.to_string());
236	
237	        if i > 0 && i % 100 == 0 {
238	            eprintln!("  Completed {} instances...", i);
239	        }
240	    }
241	
242	    eprintln!("Done. Output written to stdout as JSON lines.");
243	}

  1	//! Instance feature extraction for learned VRP models.
  2	//!
  3	//! Extracts a 28-dimensional feature vector from a VRP instance.
  4	//! Based on research:
  5	//!   - Instance-Aware Parameter Configuration (2605.00572, 2026)
  6	//!   - RouteFinder (2406.15007, 2024)
  7	//!   - RRNCO (2503.16159, 2025)
  8	
  9	use crate::core::haversine_m;
 10	use crate::core::vrp::types::{VRPSolverInput, VRPSolverStop, VrpObjective};
 11	
 12	/// 28-dimensional normalized instance feature vector.
 13	#[derive(Debug, Clone, Default, serde::Serialize)]
 14	pub struct InstanceFeatures {
 15	    // Geometric (8)
 16	    pub n_stops_norm: f64,
 17	    pub n_vehicles_norm: f64,
 18	    pub avg_pairwise_km_norm: f64,
 19	    pub lat_spread_norm: f64,
 20	    pub lon_spread_norm: f64,
 21	    pub density_norm: f64,
 22	    pub area_km2_norm: f64,
 23	    pub depot_centroid_dist_norm: f64,
 24	
 25	    // Graph (8) — from kNN(k=10) graph of stops
 26	    pub knn_avg_degree: f64,
 27	    pub knn_max_degree: f64,
 28	    pub knn_clustering: f64,
 29	    pub knn_diameter_norm: f64,
 30	    pub knn_mst_weight_norm: f64,
 31	    pub knn_avg_shortest_path: f64,
 32	    pub knn_spectral_gap: f64,
 33	    pub knn_assortativity: f64,
 34	
 35	    // Demand (4)
 36	    pub total_demand_norm: f64,
 37	    pub demand_std_norm: f64,
 38	    pub tight_capacity_flag: f64,
 39	    pub capacity_ratio: f64,
 40	
 41	    // Distance matrix stats (4)
 42	    pub dist_mean_norm: f64,
 43	    pub dist_std_norm: f64,
 44	    pub dist_skewness: f64,
 45	    pub depot_dist_mean_norm: f64,
 46	
 47	    // Objective & interaction (4)
 48	    pub objective_min_distance: f64,
 49	    pub objective_min_time: f64,
 50	    pub objective_balance_load: f64,
 51	    pub objective_min_vehicles: f64,
 52	}
 53	
 54	impl InstanceFeatures {
 55	    /// Extract features from a VRP input. Depot is index 0.
 56	    pub fn from_input(input: &VRPSolverInput) -> Self {
 57	        let stops = &input.locations;
 58	        let n = stops.len();
 59	        if n <= 1 {
 60	            return Self::default();
 61	        }
 62	
 63	        let depot = &stops[0];
 64	        let others: Vec<&VRPSolverStop> = stops.iter().skip(1).collect();
 65	        let num_stops = others.len();
 66	
 67	        // ── Geometric features ──────────────────────────────────────────
 68	        let mut dists = Vec::new();
 69	        for (i, a) in others.iter().enumerate() {
 70	            for b in others.iter().skip(i + 1) {
 71	                dists.push(haversine_m(a.lat, a.lon, b.lat, b.lon) / 1000.0);
 72	            }
 73	        }
 74	        let avg_pairwise_km = if !dists.is_empty() {
 75	            dists.iter().sum::<f64>() / dists.len() as f64
 76	        } else {
 77	            0.0
 78	        };
 79	
 80	        let lats: Vec<f64> = others.iter().map(|s| s.lat).collect();
 81	        let lons: Vec<f64> = others.iter().map(|s| s.lon).collect();
 82	        let lat_spread = std_dev(&lats);
 83	        let lon_spread = std_dev(&lons);
 84	
 85	        let lat_km = lat_spread * 111.0;
 86	        let lon_km = lon_spread * 111.0 * depot.lat.to_radians().cos();
 87	        let area_km2 = (lat_km * lon_km).max(0.001);
 88	        let density = num_stops as f64 / area_km2;
 89	
 90	        // Centroid of stops
 91	        let centroid_lat = lats.iter().sum::<f64>() / lats.len() as f64;
 92	        let centroid_lon = lons.iter().sum::<f64>() / lons.len() as f64;
 93	        let depot_centroid_dist = haversine_m(depot.lat, depot.lon, centroid_lat, centroid_lon) / 1000.0;
 94	
 95	        // ── Demand features ───────────────────────────────────────────
 96	        let demands: Vec<f64> = others.iter().filter_map(|s| s.demand).collect();
 97	        let total_demand: f64 = demands.iter().sum();
 98	        let demand_std = std_dev(&demands);
 99	        let capacity_ratio = if input.vehicle_capacity > 0.0 {
100	            total_demand / (input.vehicle_capacity * input.num_vehicles.max(1) as f64)
101	        } else {
102	            0.0
103	        };
104	        let tight_capacity = capacity_ratio > 0.8;
105	
106	        // ── Distance matrix stats ──────────────────────────────────────
107	        let depot_dists: Vec<f64> = others
108	            .iter()
109	            .map(|s| haversine_m(depot.lat, depot.lon, s.lat, s.lon) / 1000.0)
110	            .collect();
111	        let dist_mean = if !dists.is_empty() {
112	            dists.iter().sum::<f64>() / dists.len() as f64
113	        } else {
114	            0.0
115	        };
116	        let dist_std = std_dev(&dists);
117	        let dist_skew = skewness(&dists);
118	        let depot_dist_mean = if !depot_dists.is_empty() {
119	            depot_dists.iter().sum::<f64>() / depot_dists.len() as f64
120	        } else {
121	            0.0
122	        };
123	
124	        // ── kNN graph features (k=10) ──────────────────────────────────
125	        let knn_feats = knn_graph_features(&others, 10);
126	
127	        // ── Normalization constants (from training distribution) ───────
128	        // These are approximate; the real training distribution should be used.
129	        Self {
130	            n_stops_norm: (num_stops as f64 / 500.0).min(1.0),
131	            n_vehicles_norm: (input.num_vehicles.max(1) as f64 / 20.0).min(1.0),
132	            avg_pairwise_km_norm: (avg_pairwise_km / 100.0).min(1.0),
133	            lat_spread_norm: (lat_spread / 5.0).min(1.0),
134	            lon_spread_norm: (lon_spread / 5.0).min(1.0),
135	            density_norm: (density / 50.0).min(1.0),
136	            area_km2_norm: (area_km2 / 1000.0).min(1.0),
137	            depot_centroid_dist_norm: (depot_centroid_dist / 100.0).min(1.0),
138	
139	            knn_avg_degree: knn_feats.avg_degree,
140	            knn_max_degree: knn_feats.max_degree,
141	            knn_clustering: knn_feats.clustering,
142	            knn_diameter_norm: (knn_feats.diameter / 100.0).min(1.0),
143	            knn_mst_weight_norm: (knn_feats.mst_weight / 1000.0).min(1.0),
144	            knn_avg_shortest_path: (knn_feats.avg_shortest_path / 100.0).min(1.0),
145	            knn_spectral_gap: (knn_feats.spectral_gap / 50.0).min(1.0),
146	            knn_assortativity: knn_feats.assortativity.clamp(-1.0, 1.0),
147	
148	            total_demand_norm: (total_demand / 1000.0).min(1.0),
149	            demand_std_norm: (demand_std / 100.0).min(1.0),
150	            tight_capacity_flag: if tight_capacity { 1.0 } else { 0.0 },
151	            capacity_ratio: capacity_ratio.min(1.0),
152	
153	            dist_mean_norm: (dist_mean / 100.0).min(1.0),
154	            dist_std_norm: (dist_std / 100.0).min(1.0),
155	            dist_skewness: dist_skew,
156	            depot_dist_mean_norm: (depot_dist_mean / 100.0).min(1.0),
157	
158	            objective_min_distance: match input.objective {
159	                VrpObjective::MinDistance => 1.0,
160	                _ => 0.0,
161	            },
162	            objective_min_time: match input.objective {
163	                VrpObjective::MinTime => 1.0,
164	                _ => 0.0,
165	            },
166	            objective_balance_load: match input.objective {
167	                VrpObjective::BalanceLoad => 1.0,
168	                _ => 0.0,
169	            },
170	            objective_min_vehicles: match input.objective {
171	                VrpObjective::MinVehicles => 1.0,
172	                _ => 0.0,
173	            },
174	        }
175	    }
176	
177	    /// Flatten to a dense Vec<f32> for neural network input.
178	    pub fn to_vector(&self) -> Vec<f32> {
179	        vec![
180	            self.n_stops_norm as f32,
181	            self.n_vehicles_norm as f32,
182	            self.avg_pairwise_km_norm as f32,
183	            self.lat_spread_norm as f32,
184	            self.lon_spread_norm as f32,
185	            self.density_norm as f32,
186	            self.area_km2_norm as f32,
187	            self.depot_centroid_dist_norm as f32,
188	            self.knn_avg_degree as f32,
189	            self.knn_max_degree as f32,
190	            self.knn_clustering as f32,
191	            self.knn_diameter_norm as f32,
192	            self.knn_mst_weight_norm as f32,
193	            self.knn_avg_shortest_path as f32,
194	            self.knn_spectral_gap as f32,
195	            self.knn_assortativity as f32,
196	            self.total_demand_norm as f32,
197	            self.demand_std_norm as f32,
198	            self.tight_capacity_flag as f32,
199	            self.capacity_ratio as f32,
200	            self.dist_mean_norm as f32,
201	            self.dist_std_norm as f32,
202	            self.dist_skewness as f32,
203	            self.depot_dist_mean_norm as f32,
204	            self.objective_min_distance as f32,
205	            self.objective_min_time as f32,
206	            self.objective_balance_load as f32,
207	            self.objective_min_vehicles as f32,
208	        ]
209	    }
210	}
211	
212	// ── kNN graph helpers ────────────────────────────────────────────────
213	
214	#[derive(Debug, Clone, Default)]
215	struct KnnFeatures {
216	    avg_degree: f64,
217	    max_degree: f64,
218	    clustering: f64,
219	    diameter: f64,
220	    mst_weight: f64,
221	    avg_shortest_path: f64,
222	    spectral_gap: f64,
223	    assortativity: f64,
224	}
225	
226	fn knn_graph_features(stops: &[&VRPSolverStop], k: usize) -> KnnFeatures {
227	    let n = stops.len();
228	    if n < 2 {
229	        return KnnFeatures::default();
230	    }
231	    let k = k.min(n - 1).max(1);
232	
233	    // Build distance matrix
234	    let mut dists = vec![vec![0.0; n]; n];
235	    for i in 0..n {
236	        for j in (i + 1)..n {
237	            let d = haversine_m(stops[i].lat, stops[i].lon, stops[j].lat, stops[j].lon) / 1000.0;
238	            dists[i][j] = d;
239	            dists[j][i] = d;
240	        }
241	    }
242	
243	    // kNN adjacency list
244	    let mut adj: Vec<Vec<usize>> = vec![vec![]; n];
245	    let mut degrees = vec![0usize; n];
246	    for i in 0..n {
247	        let mut neighbors: Vec<(usize, f64)> = (0..n)
248	            .filter(|&j| j != i)
249	            .map(|j| (j, dists[i][j]))
250	            .collect();
251	        neighbors.sort_by(|a, b| a.1.partial_cmp(&b.1).unwrap_or(std::cmp::Ordering::Equal));
252	        for &(j, _) in neighbors.iter().take(k) {
253	            adj[i].push(j);
254	            adj[j].push(i);
255	            degrees[i] += 1;
256	            degrees[j] += 1;
257	        }
258	    }
259	
260	    let avg_degree = degrees.iter().sum::<usize>() as f64 / n as f64;
261	    let max_degree = *degrees.iter().max().unwrap_or(&0) as f64;
262	
263	    // Clustering coefficient (local)
264	    let mut clustering_sum = 0.0;
265	    for i in 0..n {
266	        let neighbors = &adj[i];
267	        let di = neighbors.len();
268	        if di < 2 {
269	            continue;
270	        }
271	        let mut edges_between = 0;
272	        for a in 0..di {
273	            for b in (a + 1)..di {
274	                if adj[neighbors[a]].contains(&neighbors[b]) {
275	                    edges_between += 1;
276	                }
277	            }
278	        }
279	        let possible = di * (di - 1) / 2;
280	        clustering_sum += edges_between as f64 / possible as f64;
281	    }
282	    let clustering = clustering_sum / n as f64;
283	
284	    // MST weight (Prim)
285	    let mst_weight = prim_mst(&dists);
286	
287	    // Diameter & avg shortest path (Floyd-Warshall for small n)
288	    let (diameter, avg_sp) = if n <= 200 {
289	        let (_sp, diam, avg) = all_pairs_shortest_paths(&dists);
290	        (diam, avg)
291	    } else {
292	        // For large n, approximate with sampled pairs
293	        let mut max_d = 0.0;
294	        let mut sum_d = 0.0;
295	        let mut count = 0;
296	        let sample = (n * 10).min(2000);
297	        for _ in 0..sample {
298	            let i = (rand_u32() as usize) % n;
299	            let j = (rand_u32() as usize) % n;
300	            if i == j { continue; }
301	            let d = dists[i][j];
302	            if d > max_d { max_d = d; }
303	            sum_d += d;
304	            count += 1;
305	        }
306	        (max_d, if count > 0 { sum_d / count as f64 } else { 0.0 })
307	    };
308	
309	    // Spectral gap (approximate from degree sequence)
310	    let spectral_gap = max_degree - avg_degree;
311	
312	    // Assortativity (degree correlation)
313	    let mut sum_xy = 0.0;
314	    let mut sum_x = 0.0;
315	    let mut sum_y = 0.0;
316	    let mut sum_x2 = 0.0;
317	    let mut sum_y2 = 0.0;
318	    let mut edge_count = 0;
319	    for i in 0..n {
320	        for &j in &adj[i] {
321	            if i >= j { continue; }
322	            let di = degrees[i] as f64;
323	            let dj = degrees[j] as f64;
324	            sum_xy += di * dj;
325	            sum_x += di;
326	            sum_y += dj;
327	            sum_x2 += di * di;
328	            sum_y2 += dj * dj;
329	            edge_count += 1;
330	        }
331	    }
332	    let assortativity = if edge_count > 0 {
333	        let ex = sum_x / edge_count as f64;
334	        let ey = sum_y / edge_count as f64;
335	        let ex2 = sum_x2 / edge_count as f64;
336	        let ey2 = sum_y2 / edge_count as f64;
337	        let cov = (sum_xy / edge_count as f64) - ex * ey;
338	        let var_x = ex2 - ex * ex;
339	        let var_y = ey2 - ey * ey;
340	        if var_x > 0.0 && var_y > 0.0 {
341	            cov / (var_x.sqrt() * var_y.sqrt())
342	        } else {
343	            0.0
344	        }
345	    } else {
346	        0.0
347	    };
348	
349	    KnnFeatures {
350	        avg_degree,
351	        max_degree,
352	        clustering,
353	        diameter,
354	        mst_weight,
355	        avg_shortest_path: avg_sp,
356	        spectral_gap,
357	        assortativity,
358	    }
359	}
360	
361	fn prim_mst(dists: &[Vec<f64>]) -> f64 {
362	    let n = dists.len();
363	    if n == 0 {
364	        return 0.0;
365	    }
366	    let mut visited = vec![false; n];
367	    let mut min_edge = vec![f64::MAX; n];
368	    min_edge[0] = 0.0;
369	    let mut total = 0.0;
370	
371	    for _ in 0..n {
372	        let mut u = None;
373	        for i in 0..n {
374	            if !visited[i] && (u.is_none() || min_edge[i] < min_edge[u.unwrap()]) {
375	                u = Some(i);
376	            }
377	        }
378	        let u = u.unwrap();
379	        visited[u] = true;
380	        total += min_edge[u];
381	
382	        for v in 0..n {
383	            if !visited[v] && dists[u][v] < min_edge[v] {
384	                min_edge[v] = dists[u][v];
385	            }
386	        }
387	    }
388	    total
389	}
390	
391	fn all_pairs_shortest_paths(dists: &[Vec<f64>]) -> (Vec<Vec<f64>>, f64, f64) {
392	    let n = dists.len();
393	    let mut sp = dists.to_vec();
394	    for k in 0..n {
395	        for i in 0..n {
396	            for j in 0..n {
397	                if sp[i][k] + sp[k][j] < sp[i][j] {
398	                    sp[i][j] = sp[i][k] + sp[k][j];
399	                }
400	            }
401	        }
402	    }
403	    let mut max_d = 0.0;
404	    let mut sum_d = 0.0;
405	    let mut count = 0;
406	    for i in 0..n {
407	        for j in (i + 1)..n {
408	            if sp[i][j] < f64::MAX / 2.0 {
409	                if sp[i][j] > max_d {
410	                    max_d = sp[i][j];
411	                }
412	                sum_d += sp[i][j];
413	                count += 1;
414	            }
415	        }
416	    }
417	    let avg = if count > 0 { sum_d / count as f64 } else { 0.0 };
418	    (sp, max_d, avg)
419	}
