  1	//! Neural-Guided Local Search Solver.
  2	//!
  3	//! Constructs routes with sweep + nearest-neighbor, then applies neural-guided
  4	//! 2-Opt and Or-Opt improvement. Instead of evaluating all O(n²) swaps or relocations
  5	//! exhaustively, a tiny MLP (MoveScorer) scores candidate moves and only the
  6	//! top-k are considered at each iteration.
  7	//!
  8	//! Research basis: RLOR (2303.13117)
  9	
 10	use super::super::types::*;
 11	use super::super::utils::{build_sweep_routes, matrix_get_dist};
 12	use anyhow::{Context, Result};
 13	use candle_core::{Device, DType, Tensor};
 14	use candle_nn::{linear, Linear, Module, VarBuilder};
 15	use std::path::{Path, PathBuf};
 16	
 17	const MOVE_FEATURE_DIM: usize = 16;
 18	
 19	/// A tiny MLP to score local-search moves: 16 → 32 → 16 → 1
 20	pub struct MoveScorer {
 21	    lin1: Linear,
 22	    lin2: Linear,
 23	    lin3: Linear,
 24	    device: Device,
 25	}
 26	
 27	impl MoveScorer {
 28	    /// Load from a safetensors file.
 29	    pub fn from_file(path: &Path) -> Result<Self> {
 30	        let device = crate::core::ml::best_device()?;
 31	        let tensors = candle_core::safetensors::load(path, &device)
 32	            .with_context(|| format!("Failed to load safetensors from {}", path.display()))?;
 33	        let vb = VarBuilder::from_tensors(tensors, DType::F32, &device);
 34	
 35	        let lin1 = linear(MOVE_FEATURE_DIM, 32, vb.pp("lin1"))?;
 36	        let lin2 = linear(32, 16, vb.pp("lin2"))?;
 37	        let lin3 = linear(16, 1, vb.pp("lin3"))?;
 38	
 39	        Ok(Self {
 40	            lin1,
 41	            lin2,
 42	            lin3,
 43	            device,
 44	        })
 45	    }
 46	
 47	    /// Predict scores for a batch of moves.
 48	    pub fn score_moves(&self, features: &[f32]) -> Result<Vec<f32>> {
 49	        let num_moves = features.len() / MOVE_FEATURE_DIM;
 50	        if num_moves == 0 {
 51	            return Ok(Vec::new());
 52	        }
 53	
 54	        let x = Tensor::from_vec(
 55	            features.to_vec(),
 56	            (num_moves, MOVE_FEATURE_DIM),
 57	            &self.device,
 58	        )?;
 59	        let h1 = self.lin1.forward(&x)?.relu()?;
 60	        let h2 = self.lin2.forward(&h1)?.relu()?;
 61	        let out = self.lin3.forward(&h2)?;
 62	
 63	        let scores = out.to_vec2::<f32>()?;
 64	        Ok(scores.into_iter().map(|row| row[0]).collect())
 65	    }
 66	}
 67	
 68	/// Compute 16-dim feature vector for a candidate 2-opt move.
 69	fn move_features_2opt(
 70	    route: &[usize],
 71	    i: usize,
 72	    j: usize,
 73	    matrix: &DistMatrix,
 74	    route_total_dist: f64,
 75	) -> [f32; MOVE_FEATURE_DIM] {
 76	    let n = route.len();
 77	    let a = route[i - 1];
 78	    let b = route[i];
 79	    let c = route[j];
 80	    let d = route[(j + 1) % n];
 81	
 82	    let d_ab = matrix_get_dist(matrix, a, b);
 83	    let d_cd = matrix_get_dist(matrix, c, d);
 84	    let d_ac = matrix_get_dist(matrix, a, c);
 85	    let d_bd = matrix_get_dist(matrix, b, d);
 86	
 87	    let delta = (d_ac + d_bd) - (d_ab + d_cd);
 88	
 89	    let avg_edge = if n > 1 {
 90	        route_total_dist / (n - 1) as f64
 91	    } else {
 92	        1.0
 93	    };
 94	    let avg_edge = avg_edge.max(1e-6);
 95	
 96	    let seg_len = (i..=j)
 97	        .map(|k| matrix_get_dist(matrix, route[k], route[(k + 1) % n]))
 98	        .sum::<f64>();
 99	
100	    let seg_stops = (j - i + 1) as f64;
101	    let route_len = n as f64;
102	
103	    [
104	        d_ab as f32,
105	        d_cd as f32,
106	        d_ac as f32,
107	        d_bd as f32,
108	        delta as f32,
109	        (d_ab / avg_edge) as f32,
110	        (d_cd / avg_edge) as f32,
111	        (d_ac / avg_edge) as f32,
112	        (d_bd / avg_edge) as f32,
113	        seg_len as f32,
114	        (seg_len / route_total_dist.max(1e-6)) as f32,
115	        seg_stops as f32,
116	        (seg_stops / route_len) as f32,
117	        (i as f64 / route_len) as f32,
118	        (j as f64 / route_len) as f32,
119	        if delta < -1e-6 { 1.0 } else { 0.0 },
120	    ]
121	}
122	
123	/// Compute 16-dim feature vector for a candidate Or-Opt move (relocation).
124	fn move_features_oropt(
125	    _matrix: &DistMatrix,
126	    remove_gain: f64,
127	    insert_cost: f64,
128	    chain_len: usize,
129	    is_rev: bool,
130	    route_len: usize,
131	) -> [f32; MOVE_FEATURE_DIM] {
132	    let delta = insert_cost - remove_gain;
133	    [
134	        remove_gain as f32,
135	        insert_cost as f32,
136	        delta as f32,
137	        chain_len as f32,
138	        if is_rev { 1.0 } else { 0.0 },
139	        (delta / (remove_gain.abs() + 1e-6)) as f32,
140	        (chain_len as f32 / route_len as f32) as f32,
141	        0.0,
142	        0.0,
143	        0.0,
144	        0.0,
145	        0.0,
146	        0.0,
147	        0.0,
148	        0.0, // padding to 16
149	        if delta < -1e-6 { 1.0 } else { 0.0 },
150	    ]
151	}
152	
153	/// Neural-guided 2-Opt improvement for a single route.
154	fn neural_guided_two_opt(
155	    route: &mut Vec<usize>,
156	    matrix: &DistMatrix,
157	    scorer: Option<&MoveScorer>,
158	    max_iter: u32,
159	) {
160	    let n = route.len();
161	    if n <= 3 {
162	        return;
163	    }
164	
165	    let route_dist = |r: &[usize]| -> f64 {
166	        (0..r.len() - 1)
167	            .map(|k| matrix_get_dist(matrix, r[k], r[k + 1]))
168	            .sum()
169	    };
170	
171	    let mut improved = true;
172	    let mut iter = 0;
173	
174	    while improved && iter < max_iter {
175	        improved = false;
176	        iter += 1;
177	
178	        let total_dist = route_dist(route);
179	        let mut features = Vec::new();
180	        let mut meta = Vec::new();
181	
182	        for i in 1..n - 2 {
183	            for j in (i + 1)..n - 1 {
184	                let a = route[i - 1];
185	                let b = route[i];
186	                let c = route[j];
187	                let d = route[(j + 1) % n];
188	
189	                let before = matrix_get_dist(matrix, a, b) + matrix_get_dist(matrix, c, d);
190	                let after = matrix_get_dist(matrix, a, c) + matrix_get_dist(matrix, b, d);
191	                let delta = after - before;
192	
193	                if scorer.is_some() || delta < -1e-9 {
194	                    features.extend_from_slice(&move_features_2opt(
195	                        route,
196	                        i,
197	                        j,
198	                        matrix,
199	                        total_dist,
200	                    ));
201	                    meta.push((i, j, delta));
202	                }
203	            }
204	        }
205	
206	        if meta.is_empty() {
207	            break;
208	        }
209	
210	        let mut scored: Vec<(usize, f64)> = if let Some(s) = scorer {
211	            match s.score_moves(&features) {
212	                Ok(scores) => scores
213	                    .into_iter()
214	                    .enumerate()
215	                    .map(|(idx, score)| (idx, score as f64))
216	                    .collect(),
217	                Err(_) => meta
218	                    .iter()
219	                    .enumerate()
220	                    .map(|(idx, (_, _, delta))| (idx, -delta))
221	                    .collect(),
222	            }
223	        } else {
224	            meta.iter()
225	                .enumerate()
226	                .map(|(idx, (_, _, delta))| (idx, -delta))
227	                .collect()
228	        };
229	
230	        scored.sort_by(|a, b| b.1.partial_cmp(&a.1).unwrap_or(std::cmp::Ordering::Equal));
231	        let top_k = if scorer.is_some() {
232	            scored.len().min(50)
233	        } else {
234	            scored.len().min(1)
235	        };
236	
237	        for &(idx, _) in &scored[..top_k] {
238	            let (i, j, delta) = meta[idx];
239	            if delta < -1e-9 {
240	                route[i..=j].reverse();
241	                improved = true;
242	                break;
243	            }
244	        }
245	    }
246	}
247	
248	/// Neural-guided Or-Opt improvement across routes.
249	fn neural_guided_or_opt(
250	    routes: &mut Vec<Vec<usize>>,
251	    matrix: &DistMatrix,
252	    scorer: Option<&MoveScorer>,
253	    max_passes: u32,
254	) {
255	    let mut improved = true;
256	    let mut passes = 0;
257	
258	    while improved && passes < max_passes {
259	        improved = false;
260	        passes += 1;
261	
262	        let mut features = Vec::new();
263	        let mut meta = Vec::new();
264	
265	        for ri in 0..routes.len() {
266	            let route_a = &routes[ri];
267	            if route_a.len() < 4 {
268	                continue;
269	            }
270	
271	            for k in 1..=3 {
272	                for pos in 1..(route_a.len().saturating_sub(k)) {
273	                    let chain_first = route_a[pos];
274	                    let chain_last = route_a[pos + k - 1];
275	                    let prev = route_a[pos - 1];
276	                    let next = route_a[pos + k];
277	
278	                    let remove_gain = matrix_get_dist(matrix, prev, chain_first)
279	                        + matrix_get_dist(matrix, chain_last, next)
280	                        - matrix_get_dist(matrix, prev, next);
281	
282	                    for rj in 0..routes.len() {
283	                        let route_b = &routes[rj];
284	                        for ins in 0..route_b.len().saturating_sub(1) {
285	                            if ri == rj && ins >= pos.saturating_sub(1) && ins < pos + k {
286	                                continue;
287	                            }
288	
289	                            let a_node = route_b[ins];
290	                            let b_node = route_b[ins + 1];
291	
292	                            let cost_fwd = matrix_get_dist(matrix, a_node, chain_first)
293	                                + matrix_get_dist(matrix, chain_last, b_node)
294	                                - matrix_get_dist(matrix, a_node, b_node);
295	
296	                            let delta_fwd = cost_fwd - remove_gain;
297	                            if scorer.is_some() || delta_fwd < -1e-9 {
298	                                features.extend_from_slice(&move_features_oropt(
299	                                    matrix,
300	                                    remove_gain,
301	                                    cost_fwd,
302	                                    k,
303	                                    false,
304	                                    route_a.len(),
305	                                ));
306	                                meta.push((ri, rj, pos, k, ins, false, delta_fwd));
307	                            }
308	                        }
309	                    }
310	                }
311	            }
312	        }
313	
314	        if meta.is_empty() {
315	            break;
316	        }
317	
318	        let mut scored: Vec<(usize, f64)> = if let Some(s) = scorer {
319	            match s.score_moves(&features) {
320	                Ok(scores) => scores
321	                    .into_iter()
322	                    .enumerate()
323	                    .map(|(idx, score)| (idx, score as f64))
324	                    .collect(),
325	                Err(_) => meta.iter().enumerate().map(|(idx, m)| (idx, -m.6)).collect(),
326	            }
327	        } else {
328	            meta.iter().enumerate().map(|(idx, m)| (idx, -m.6)).collect()
329	        };
330	
331	        scored.sort_by(|a, b| b.1.partial_cmp(&a.1).unwrap_or(std::cmp::Ordering::Equal));
332	        let top_k = if scorer.is_some() {
333	            scored.len().min(20)
334	        } else {
335	            scored.len().min(1)
336	        };
337	
338	        for &(idx, _) in &scored[..top_k] {
339	            let (ri, rj, pos, k, ins, _rev, delta) = meta[idx];
340	            if delta < -1e-9 {
341	                let chain: Vec<usize> = routes[ri][pos..pos + k].to_vec();
342	                let insert_chain = chain; // Simplified, not supporting rev for now
343	
344	                if ri == rj {
345	                    let mut r = routes[ri].clone();
346	                    r.splice(pos..pos + k, std::iter::empty());
347	                    let adj_ins = if ins >= pos { ins - k } else { ins };
348	                    r.splice(adj_ins + 1..adj_ins + 1, insert_chain);
349	                    routes[ri] = r;
350	                } else {
351	                    routes[ri].splice(pos..pos + k, std::iter::empty());
352	                    routes[rj].splice(ins + 1..ins + 1, insert_chain);
353	                }
354	                improved = true;
355	                break;
356	            }
357	        }
358	    }
359	}
360	fn solve(
361	    matrix: &DistMatrix,
362	    locations: &[VRPSolverStop],
363	    num_vehicles: usize,
364	    hyperparams: Option<&SolverHyperparams>,
365	) -> SolveResult {
366	    let n = matrix.len();
367	    if n <= 1 {
368	        return SolveResult {
369	            routes: vec![vec![0]],
370	            total_distance: 0.0,
371	            total_time: 0.0,
372	        };
373	    }
374	
375	    let max_iterations = hyperparams.map(|p| p.max_iterations).unwrap_or(200);
376	
377	    let path = default_model_path();
378	    let scorer = if path.exists() {
379	        MoveScorer::from_file(&path).ok()
380	    } else {
381	        None
382	    };
383	
384	    if scorer.is_some() {
385	        tracing::info!("Neural-guided solver: MoveScorer loaded. Max iterations: {}", max_iterations);
386	    } else {
387	        tracing::info!(
388	            "Neural-guided solver: MoveScorer not available, falling back to exhaustive 2-opt. Max iterations: {}",
389	            max_iterations
390	        );
391	    }
392	
393	    let mut routes = build_sweep_routes(matrix, locations, num_vehicles);
394	
395	    for route in &mut routes {
396	        neural_guided_two_opt(route, matrix, scorer.as_ref(), max_iterations);
397	    }
398	
399	
400	    neural_guided_or_opt(&mut routes, matrix, scorer.as_ref(), max_iterations / 4);
401	
402	    let final_routes: Vec<Vec<usize>> = routes.into_iter().filter(|r| r.len() > 2).collect();
403	    if final_routes.is_empty() {
404	        return SolveResult {
405	            routes: vec![vec![0, 0]],
406	            total_distance: 0.0,
407	            total_time: 0.0,
408	        };
409	    }
410	
411	    let mut total_distance = 0.0;
412	    let mut total_time = 0.0;
413	    for r in &final_routes {
414	        for i in 0..r.len() - 1 {
415	            total_distance += matrix_get_dist(matrix, r[i], r[i + 1]);
416	            total_time += matrix
417	                .get(r[i])
418	                .and_then(|row| row.get(r[i + 1]))
419	                .map(|c| c.time)
420	                .unwrap_or(0.0);
421	        }
422	    }
423	
424	    SolveResult {
425	        routes: final_routes,
426	        total_distance,
427	        total_time,
428	    }
429	}
430	
431	pub fn default_model_path() -> PathBuf {
432	    if let Ok(exe) = std::env::current_exe() {
433	        if let Some(parent) = exe.parent() {
434	            let path = parent.join("models").join("move_scorer.safetensors");
435	            if path.exists() {
436	                return path;
437	            }
438	        }
439	    }
440	    PathBuf::from("models/move_scorer.safetensors")
441	}
