  1	//! Machine-learning utilities for route optimization.
  2	//!
  3	//! Provides lightweight, deterministic predictors and scorers that can be
  4	//! swapped for learned models later.  All functions are pure (no I/O) so
  5	//! they work in MCP handlers, TUI callbacks, and WASM targets.
  6	
  7	use super::vrp::types::{VRPSolverInput, VRPSolverOutput, VrpObjective, VRPSolverStop};
  8	use super::haversine_m;
  9	
 10	// ── Route feature extraction ───────────────────────────────────────────
 11	
 12	/// Geometric and topological features of a VRP instance.
 13	#[derive(Debug, Clone, Default)]
 14	pub struct RouteFeatures {
 15	    /// Number of stops (excluding depot).
 16	    pub num_stops: usize,
 17	    /// Number of vehicles requested.
 18	    pub num_vehicles: usize,
 19	    /// Average pairwise haversine distance in km.
 20	    pub avg_pairwise_km: f64,
 21	    /// Standard deviation of stop latitudes (proxy for north-south spread).
 22	    pub lat_spread: f64,
 23	    /// Standard deviation of stop longitudes (proxy for east-west spread).
 24	    pub lon_spread: f64,
 25	    /// Ratio of spread in km to stop count (density proxy).
 26	    pub density: f64,
 27	    /// Whether capacity constraints are tight.
 28	    pub tight_capacity: bool,
 29	    /// Optimization objective.
 30	    pub objective: VrpObjective,
 31	}
 32	
 33	impl RouteFeatures {
 34	    /// Extract features from a VRP input (stops + depot at index 0).
 35	    pub fn from_input(input: &VRPSolverInput) -> Self {
 36	        let stops = &input.locations;
 37	        let n = stops.len();
 38	        if n <= 1 {
 39	            return Self {
 40	                num_stops: 0,
 41	                num_vehicles: input.num_vehicles.max(1),
 42	                ..Default::default()
 43	            };
 44	        }
 45	
 46	        let depot = &stops[0];
 47	        let others: Vec<&VRPSolverStop> = stops.iter().skip(1).collect();
 48	
 49	        // Pairwise distances
 50	        let mut dists = Vec::new();
 51	        for (i, a) in others.iter().enumerate() {
 52	            for b in others.iter().skip(i + 1) {
 53	                dists.push(haversine_m(a.lat, a.lon, b.lat, b.lon) / 1000.0);
 54	            }
 55	        }
 56	        let avg_pairwise_km = if !dists.is_empty() {
 57	            dists.iter().sum::<f64>() / dists.len() as f64
 58	        } else {
 59	            0.0
 60	        };
 61	
 62	        // Spread
 63	        let lats: Vec<f64> = others.iter().map(|s| s.lat).collect();
 64	        let lons: Vec<f64> = others.iter().map(|s| s.lon).collect();
 65	        let lat_spread = std_dev(&lats);
 66	        let lon_spread = std_dev(&lons);
 67	
 68	        // Approx density: km² spread / stop count
 69	        let lat_km = lat_spread * 111.0; // 1° lat ≈ 111 km
 70	        let lon_km = lon_spread * 111.0 * depot.lat.to_radians().cos();
 71	        let area_km2 = (lat_km * lon_km).max(0.001);
 72	        let density = others.len() as f64 / area_km2;
 73	
 74	        // Capacity tightness
 75	        let total_demand: f64 = others.iter().filter_map(|s| s.demand).sum();
 76	        let tight_capacity = total_demand > input.vehicle_capacity * 0.8;
 77	
 78	        Self {
 79	            num_stops: others.len(),
 80	            num_vehicles: input.num_vehicles.max(1),
 81	            avg_pairwise_km,
 82	            lat_spread,
 83	            lon_spread,
 84	            density,
 85	            tight_capacity,
 86	            objective: input.objective.clone(),
 87	        }
 88	    }
 89	}
 90	
 91	fn std_dev(vals: &[f64]) -> f64 {
 92	    if vals.len() < 2 {
 93	        return 0.0;
 94	    }
 95	    let mean = vals.iter().sum::<f64>() / vals.len() as f64;
 96	    let var = vals.iter().map(|v| (v - mean).powi(2)).sum::<f64>() / (vals.len() - 1) as f64;
 97	    var.sqrt()
 98	}
 99	
100	// ── Solver recommendation ─────────────────────────────────────────────
101	
102	/// Recommend a solver id and a confidence score [0,1] for the given instance.
103	///
104	/// Rules derived from heuristics informed by EARLI (2025) and RouteFinder (2024)
105	/// literature: small/dense instances prefer fast constructive heuristics,
106	/// large/sparse or multi-objective instances benefit from local-search metaheuristics.
107	pub fn predict_solver(features: &RouteFeatures) -> SolverPrediction {
108	    let n = features.num_stops;
109	    let v = features.num_vehicles;
110	
111	    // Score each solver 0–1; higher = better fit
112	    let mut scores: Vec<(&str, f64)> = vec![
113	        ("default", 0.5),
114	        ("clarke_wright", 0.5),
115	        ("sweep", 0.5),
116	        ("two_opt", 0.5),
117	        ("or_opt", 0.5),
118	    ];
119	
120	    // Adjust scores based on instance characteristics
121	    for (id, score) in scores.iter_mut() {
122	        match *id {
123	            "default" => {
124	                // Zone-cluster + NN + 2-opt: good default, especially for dense areas
125	                *score += 0.1;
126	                if features.density > 5.0 {
127	                    *score += 0.15; // dense clusters
128	                }
129	                if n <= 20 {
130	                    *score += 0.1; // small instances
131	                }
132	            }
133	            "clarke_wright" => {
134	                // Savings: excellent for capacity-constrained, medium size
135	                if features.tight_capacity {
136	                    *score += 0.2;
137	                }
138	                if n >= 20 && n <= 200 {
139	                    *score += 0.1;
140	                }
141	                if v >= 2 && v <= 10 {
142	                    *score += 0.1;
143	                }
144	                if features.objective == VrpObjective::MinDistance {
145	                    *score += 0.05;
146	                }
147	            }
148	            "sweep" => {
149	                // Sweep: geometric, good for radial layouts with many vehicles
150	                if v >= 5 {
151	                    *score += 0.2;
152	                }
153	                if features.lat_spread > 0.5 || features.lon_spread > 0.5 {
154	                    *score += 0.1; // wide spread
155	                }
156	                if features.objective == VrpObjective::BalanceLoad {
157	                    *score += 0.1;
158	                }
159	            }
160	            "two_opt" => {
161	                // 2-Opt untangling: good for post-processing or medium routes
162	                if n >= 30 && n <= 300 {
163	                    *score += 0.1;
164	                }
165	            }
166	            "or_opt" => {
167	                // Or-Opt metaheuristic: best for large instances, balance, time objectives
168	                if n > 100 {
169	                    *score += 0.15;
170	                }
171	                if features.objective == VrpObjective::BalanceLoad {
172	                    *score += 0.15;
173	                }
174	                if features.objective == VrpObjective::MinTime {
175	                    *score += 0.1;
176	                }
177	                if features.tight_capacity {
178	                    *score += 0.05;
179	                }
180	            }
181	            _ => {}
182	        }
183	    }
184	
185	    scores.sort_by(|a, b| b.1.partial_cmp(&a.1).unwrap_or(std::cmp::Ordering::Equal));
186	    let (best_id, best_score) = scores[0];
187	    let runner_up = scores.get(1).map(|(id, s)| (id.to_string(), *s));
188	
189	    SolverPrediction {
190	        recommended: best_id.to_string(),
191	        confidence: best_score.clamp(0.0, 1.0),
192	        runner_up,
193	        all_scores: scores.into_iter().map(|(id, s)| (id.to_string(), s.clamp(0.0, 1.0))).collect(),
194	        features: features.clone(),
195	    }
196	}
197	
198	#[derive(Debug, Clone)]
199	pub struct SolverPrediction {
200	    pub recommended: String,
201	    pub confidence: f64,
202	    pub runner_up: Option<(String, f64)>,
203	    pub all_scores: Vec<(String, f64)>,
204	    pub features: RouteFeatures,
205	}
206	
207	// ── Route quality scoring ─────────────────────────────────────────────
208	
209	/// Score a solved route on multiple dimensions.  Each sub-score is 0–100.
210	/// Higher is better (more efficient, more balanced, fewer bad turns).
211	#[derive(Debug, Clone, Default, serde::Serialize)]
212	pub struct RouteQualityScore {
213	    pub distance_efficiency: f64,
214	    pub load_balance: f64,
215	    pub turn_quality: f64,
216	    pub coverage: f64,
217	    pub overall: f64,
218	}
219	
220	/// Score a route output given the original input.
221	///
222	/// * `distance_efficiency` — ratio of straight-line lower bound to actual distance.
223	/// * `load_balance` — 100 when all routes have equal stop counts, 0 when max imbalance.
224	/// * `turn_quality` — penalizes U-turns and left turns relative to straights.
225	/// * `coverage` — what fraction of requested stops were assigned.
226	pub fn score_route(input: &VRPSolverInput, output: &VRPSolverOutput) -> RouteQualityScore {
227	    let n_stops = input.locations.len().saturating_sub(1).max(1);
228	
229	    // --- Distance efficiency ---
230	    // Lower bound: sum of depot→stop distances (star tour)
231	    let depot = &input.locations[0];
232	    let star_lower_km: f64 = input
233	        .locations
234	        .iter()
235	        .skip(1)
236	        .map(|s| haversine_m(depot.lat, depot.lon, s.lat, s.lon) / 1000.0)
237	        .sum::<f64>()
238	        * 2.0; // out and back
239	    let actual_km: f64 = output.total_distance_km.parse().unwrap_or(f64::MAX);
240	    let distance_efficiency = if actual_km > 0.0 {
241	        ((star_lower_km / actual_km) * 100.0).clamp(0.0, 100.0)
242	    } else {
243	        0.0
244	    };
245	
246	    // --- Load balance ---
247	    let load_balance = if let Some(ref routes) = output.routes {
248	        let counts: Vec<usize> = routes.iter().map(|r| r.len().saturating_sub(2)).collect();
249	        if counts.is_empty() || counts.iter().sum::<usize>() == 0 {
250	            100.0
251	        } else {
252	            let mean = counts.iter().sum::<usize>() as f64 / counts.len() as f64;
253	            let max_dev = counts
254	                .iter()
255	                .map(|&c| (c as f64 - mean).abs())
256	                .fold(0.0f64, f64::max);
257	            let max_possible = mean.max(n_stops as f64 - mean);
258	            (100.0 * (1.0 - max_dev / max_possible.max(1.0))).clamp(0.0, 100.0)
259	        }
260	    } else {
261	        // Single route: perfectly balanced by definition
262	        100.0
263	    };
264	
265	    // --- Turn quality ---
266	    // Count turns from stop-level routes if available, else assume straight
267	    let (left, right, u_turn, straight) = if let Some(ref routes) = output.routes {
268	        routes.iter().fold((0, 0, 0, 0), |(l, r, u, s), route| {
269	            if route.len() < 3 {
270	                return (l, r, u, s + route.len().saturating_sub(2) as u32);
271	            }
272	            let mut counts = (l, r, u, s);
273	            for i in 1..route.len() - 1 {
274	                let prev = &route[i - 1];
275	                let curr = &route[i];
276	                let next = &route[i + 1];
277	                let delta = bearing_delta(prev, curr, next);
278	                let d = delta.abs();
279	                if d > 150.0 {
280	                    counts.2 += 1; // u-turn
281	                } else if d > 45.0 && d <= 135.0 {
282	                    if delta < 0.0 {
283	                        counts.0 += 1; // left
284	                    } else {
285	                        counts.1 += 1; // right
286	                    }
287	                } else {
288	                    counts.3 += 1; // straight
289	                }
290	            }
291	            counts
292	        })
293	    } else {
294	        (0, 0, 0, n_stops.saturating_sub(1) as u32)
295	    };
296	    let total_turns = left + right + u_turn + straight;
297	    let turn_quality = if total_turns > 0 {
298	        let penalty = u_turn as f64 * 2.0 + left as f64 * 0.3 + right as f64 * 0.1;
299	        (100.0 - penalty * 100.0 / total_turns as f64).clamp(0.0, 100.0)
300	    } else {
301	        100.0
302	    };
303	
304	    // --- Coverage ---
305	    let assigned = output.stops.len().saturating_sub(1).max(1);
306	    let coverage = (100.0 * assigned as f64 / n_stops as f64).clamp(0.0, 100.0);
307	
308	    // --- Overall ---
309	    let overall = (distance_efficiency * 0.35
310	        + load_balance * 0.25
311	        + turn_quality * 0.20
312	        + coverage * 0.20)
313	        .clamp(0.0, 100.0);
314	
315	    RouteQualityScore {
316	        distance_efficiency: round2(distance_efficiency),
317	        load_balance: round2(load_balance),
318	        turn_quality: round2(turn_quality),
319	        coverage: round2(coverage),
320	        overall: round2(overall),
321	    }
322	}
323	
324	fn bearing_delta(a: &VRPSolverStop, b: &VRPSolverStop, c: &VRPSolverStop) -> f64 {
325	    let b1 = bearing(a.lat, a.lon, b.lat, b.lon);
326	    let b2 = bearing(b.lat, b.lon, c.lat, c.lon);
327	    let d = b2 - b1;
328	    let d = ((d + 180.0) % 360.0) - 180.0;
329	    d
330	}
331	
332	fn bearing(lat1: f64, lon1: f64, lat2: f64, lon2: f64) -> f64 {
333	    let dlon = (lon2 - lon1).to_radians();
334	    let lat1_r = lat1.to_radians();
335	    let lat2_r = lat2.to_radians();
336	    let x = dlon.cos() * lat2_r.sin();
337	    let y = lat1_r.cos() * lat2_r.sin() - lat1_r.sin() * lat2_r.cos() * dlon.cos();
338	    let br = y.atan2(x);
339	    (br.to_degrees() + 360.0) % 360.0
340	}
341	
342	fn round2(v: f64) -> f64 {
343	    (v * 100.0).round() / 100.0
344	}
345	
346	// ── Route embedding / similarity (feature-vector representation) ──────
347	
348	/// Produce a dense feature vector that can be used for similarity search
349	/// or as input to a learned model.  12 dimensions, normalized to ~[0,1].
350	pub fn route_feature_vector(features: &RouteFeatures) -> Vec<f32> {
351	    let n = features.num_stops as f64;
352	    vec![
353	        (n / 500.0).min(1.0) as f32,
354	        (features.num_vehicles as f64 / 20.0).min(1.0) as f32,
355	        (features.avg_pairwise_km / 100.0).min(1.0) as f32,
356	        (features.lat_spread / 5.0).min(1.0) as f32,
357	        (features.lon_spread / 5.0).min(1.0) as f32,
358	        (features.density / 50.0).min(1.0) as f32,
359	        if features.tight_capacity { 1.0 } else { 0.0 },
360	        match features.objective {
361	            VrpObjective::MinDistance => 0.0,
362	            VrpObjective::MinTime => 0.33,
363	            VrpObjective::BalanceLoad => 0.66,
364	            VrpObjective::MinVehicles => 1.0,
365	        } as f32,
366	        // Higher-order interactions
367	        (n / features.num_vehicles.max(1) as f64 / 50.0).min(1.0) as f32,
368	        (features.avg_pairwise_km * features.num_vehicles as f64 / 500.0).min(1.0) as f32,
369	        (features.lat_spread * features.lon_spread).min(1.0) as f32,
370	        (features.density * n / 1000.0).min(1.0) as f32,
371	    ]
372	}
