  1	//! Learned solver selector using a small MLP in Candle.
  2	//!
  3	//! Replaces the rule-based `predict_solver` in `ml_legacy.rs`.
  4	//!
  5	//! Architecture: 28 → 128 → 64 → 5  (input → hidden → hidden → num_solvers)
  6	//! Activation: ReLU hidden, Softmax output.
  7	//!
  8	//! Weights are loaded from a safetensors file at runtime.
  9	//! If the model file is missing, falls back to the rule-based selector.
 10	
 11	use crate::core::ml::features::InstanceFeatures;
 12	use crate::core::ml_legacy::predict_solver as rule_predict_solver;
 13	use crate::core::vrp::types::VRPSolverInput;
 14	use anyhow::{Context, Result};
 15	use candle_core::{Device, Tensor, DType};
 16	use candle_nn::{linear, Module, VarBuilder, Linear};
 17	use serde::{Deserialize, Serialize};
 18	use std::path::Path;
 19	
 20	const NUM_FEATURES: usize = 28;
 21	const HIDDEN1: usize = 128;
 22	const HIDDEN2: usize = 64;
 23	const NUM_SOLVERS: usize = 6;
 24	
 25	const SOLVER_IDS: [&str; NUM_SOLVERS] = [
 26	    "default",
 27	    "clarke_wright",
 28	    "sweep",
 29	    "or_opt",
 30	    "two_opt",
 31	    "neural_guided",
 32	];
 33	
 34	/// Learned MLP solver selector.
 35	pub struct NeuralSelector {
 36	    lin1: Linear,
 37	    lin2: Linear,
 38	    lin3: Linear,
 39	    device: Device,
 40	}
 41	
 42	impl NeuralSelector {
 43	    /// Load from a safetensors file.
 44	    pub fn from_file(path: &Path) -> Result<Self> {
 45	        let device = crate::core::ml::best_device()?;
 46	        let tensors = candle_core::safetensors::load(path, &device)
 47	            .with_context(|| format!("Failed to load safetensors from {}", path.display()))?;
 48	        let vb = VarBuilder::from_tensors(tensors, DType::F32, &device);
 49	        let lin1 = linear(NUM_FEATURES, HIDDEN1, vb.pp("lin1"))?;
 50	        let lin2 = linear(HIDDEN1, HIDDEN2, vb.pp("lin2"))?;
 51	        let lin3 = linear(HIDDEN2, NUM_SOLVERS, vb.pp("lin3"))?;
 52	        Ok(Self { lin1, lin2, lin3, device })
 53	    }
 54	
 55	    /// Predict best solver using classification (argmax probability).
 56	    pub fn predict(&self,
 57	        features: &InstanceFeatures,
 58	    ) -> Result<NeuralPrediction> {
 59	        let x = features.to_vector();
 60	        let input = Tensor::from_vec(x, (1, NUM_FEATURES), &self.device)?;
 61	        let h1 = self.lin1.forward(&input)?.relu()?;
 62	        let h2 = self.lin2.forward(&h1)?.relu()?;
 63	        let logits = self.lin3.forward(&h2)?;
 64	        let probs = candle_nn::ops::softmax(&logits, 1)?;
 65	        let vals: Vec<f32> = probs.squeeze(0)?.to_vec1()?;
 66	        
 67	        let mut indexed: Vec<(usize, f32)> = vals.iter().enumerate().map(|(i, &v)| (i, v)).collect();
 68	        // Sort by probability DESCENDING (higher is better)
 69	        indexed.sort_by(|a, b| b.1.partial_cmp(&a.1).unwrap_or(std::cmp::Ordering::Equal));
 70	
 71	        let best_idx = indexed[0].0;
 72	        let best_prob = indexed[0].1;
 73	        let runner_up = indexed.get(1).map(|(i, v)| (SOLVER_IDS[*i].to_string(), *v));
 74	
 75	        let all_scores: Vec<(String, f64)> = indexed
 76	            .iter()
 77	            .map(|(i, v)| (SOLVER_IDS[*i].to_string(), *v as f64))
 78	            .collect();
 79	
 80	        Ok(NeuralPrediction {
 81	            recommended: SOLVER_IDS[best_idx].to_string(),
 82	            confidence: best_prob as f64,
 83	            runner_up,
 84	            all_scores,
 85	        })
 86	    }
 87	}
 88	
 89	/// Prediction result from the neural selector.
 90	#[derive(Debug, Clone, Serialize, Deserialize)]
 91	pub struct NeuralPrediction {
 92	    pub recommended: String,
 93	    pub confidence: f64,
 94	    pub runner_up: Option<(String, f32)>,
 95	    pub all_scores: Vec<(String, f64)>,
 96	}
 97	
 98	/// High-level API: predict the best solver for a VRP instance.
 99	///
100	/// Tries to load the neural model from `model_path`. If missing or failed,
101	/// falls back to the legacy rule-based selector.
102	pub fn predict_solver(
103	    input: &VRPSolverInput,
104	    model_path: Option<&Path>,
105	) -> Result<NeuralPrediction> {
106	    let features = InstanceFeatures::from_input(input);
107	
108	    if let Some(path) = model_path {
109	        if path.exists() {
110	            match NeuralSelector::from_file(path) {
111	                Ok(selector) => {
112	                    match selector.predict(&features) {
113	                        Ok(pred) => return Ok(pred),
114	                        Err(e) => {
115	                            println!("DEBUG: Neural selector inference failed: {}", e);
116	                            tracing::warn!("Neural selector inference failed: {}. Falling back to rule-based.", e);
117	                        }
118	                    }
119	                }
120	                Err(e) => {
121	                    println!("DEBUG: Failed to load neural selector from {:?}: {}", path, e);
122	                    tracing::warn!("Failed to load neural selector: {}. Falling back to rule-based.", e);
123	                }
124	            }
125	        } else {
126	            println!("DEBUG: model_path {:?} does not exist", path);
127	        }
128	    }
129	
130	    // Fallback: rule-based
131	    let legacy = rule_predict_solver(&crate::core::ml_legacy::RouteFeatures::from_input(input)
132	    );
133	    let all_scores: Vec<(String, f64)> = legacy.all_scores;
134	    let runner_up = legacy.runner_up.map(|(id, score)| (id, score as f32));
135	    Ok(NeuralPrediction {
136	        recommended: legacy.recommended,
137	        confidence: legacy.confidence,
138	        runner_up,
139	        all_scores,
140	    })
141	}
