361	fn prim_mst(dists: &[Vec<f64>]) -> f64 {
362	    let n = dists.len();
363	    if n == 0 {
364	        return 0.0;
365	    }
366	    let mut visited = vec![false; n];
367	    let mut min_edge = vec![f64::MAX; n];
368	    min_edge[0] = 0.0;
369	    let mut total = 0.0;
370	
371	    for _ in 0..n {
372	        let mut u = None;
373	        for i in 0..n {
374	            if !visited[i] && (u.is_none() || min_edge[i] < min_edge[u.unwrap()]) {
375	                u = Some(i);
376	            }
377	        }
378	        let u = u.unwrap();
379	        visited[u] = true;
380	        total += min_edge[u];
381	
382	        for v in 0..n {
383	            if !visited[v] && dists[u][v] < min_edge[v] {
384	                min_edge[v] = dists[u][v];
385	            }
386	        }
387	    }
388	    total
389	}
390	
391	fn all_pairs_shortest_paths(dists: &[Vec<f64>]) -> (Vec<Vec<f64>>, f64, f64) {
392	    let n = dists.len();
393	    let mut sp = dists.to_vec();
394	    for k in 0..n {
395	        for i in 0..n {
396	            for j in 0..n {
397	                if sp[i][k] + sp[k][j] < sp[i][j] {
398	                    sp[i][j] = sp[i][k] + sp[k][j];
399	                }
400	            }
401	        }
402	    }
403	    let mut max_d = 0.0;
404	    let mut sum_d = 0.0;
405	    let mut count = 0;
406	    for i in 0..n {
407	        for j in (i + 1)..n {
408	            if sp[i][j] < f64::MAX / 2.0 {
409	                if sp[i][j] > max_d {
410	                    max_d = sp[i][j];
411	                }
412	                sum_d += sp[i][j];
413	                count += 1;
414	            }
415	        }
416	    }
417	    let avg = if count > 0 { sum_d / count as f64 } else { 0.0 };
418	    (sp, max_d, avg)
419	}
