433	
434	fn std_dev(vals: &[f64]) -> f64 {
435	    if vals.len() < 2 {
436	        return 0.0;
437	    }
438	    let mean = vals.iter().sum::<f64>() / vals.len() as f64;
439	    let var = vals.iter().map(|v| (v - mean).powi(2)).sum::<f64>() / (vals.len() - 1) as f64;
440	    var.sqrt()
441	}
442	
443	fn skewness(vals: &[f64]) -> f64 {
444	    if vals.len() < 3 {
445	        return 0.0;
446	    }
447	    let mean = vals.iter().sum::<f64>() / vals.len() as f64;
448	    let std = std_dev(vals);
449	    if std == 0.0 {
450	        return 0.0;
451	    }
452	    let n = vals.len() as f64;
453	    let m3 = vals.iter().map(|v| (v - mean).powi(3)).sum::<f64>() / n;
454	    m3 / std.powi(3)
455	}
