  1	//! Neural-Guided Local Search Solver.
  2	//!
  3	//! Constructs routes with sweep + nearest-neighbor, then applies neural-guided
  4	//! 2-Opt and Or-Opt improvement. Instead of evaluating all O(n²) swaps or relocations
  5	//! exhaustively, a tiny MLP (MoveScorer) scores candidate moves and only the
  6	//! top-k are considered at each iteration.
  7	//!
  8	//! Research basis: RLOR (2303.13117)
  9	
 10	use super::super::types::*;
 11	use super::super::utils::{build_sweep_routes, matrix_get_dist};
 12	use anyhow::{Context, Result};
 13	use candle_core::{Device, DType, Tensor};
 14	use candle_nn::{linear, Linear, Module, VarBuilder};
 15	use std::path::{Path, PathBuf};
 16	
 17	const MOVE_FEATURE_DIM: usize = 16;
 18	
 19	/// A tiny MLP to score local-search moves: 16 → 32 → 16 → 1
 20	pub struct MoveScorer {
 21	    lin1: Linear,
 22	    lin2: Linear,
 23	    lin3: Linear,
 24	    device: Device,
 25	}
 26	
 27	impl MoveScorer {
 28	    /// Load from a safetensors file.
 29	    pub fn from_file(path: &Path) -> Result<Self> {
 30	        let device = crate::core::ml::best_device()?;
 31	        let tensors = candle_core::safetensors::load(path, &device)
 32	            .with_context(|| format!("Failed to load safetensors from {}", path.display()))?;
 33	        let vb = VarBuilder::from_tensors(tensors, DType::F32, &device);
 34	
 35	        let lin1 = linear(MOVE_FEATURE_DIM, 32, vb.pp("lin1"))?;
 36	        let lin2 = linear(32, 16, vb.pp("lin2"))?;
 37	        let lin3 = linear(16, 1, vb.pp("lin3"))?;
 38	
 39	        Ok(Self {
 40	            lin1,
 41	            lin2,
 42	            lin3,
 43	            device,
 44	        })
 45	    }
 46	
 47	    /// Predict scores for a batch of moves.
 48	    pub fn score_moves(&self, features: &[f32]) -> Result<Vec<f32>> {
 49	        let num_moves = features.len() / MOVE_FEATURE_DIM;
 50	        if num_moves == 0 {
 51	            return Ok(Vec::new());
 52	        }
 53	
 54	        let x = Tensor::from_vec(
 55	            features.to_vec(),
 56	            (num_moves, MOVE_FEATURE_DIM),
 57	            &self.device,
 58	        )?;
 59	        let h1 = self.lin1.forward(&x)?.relu()?;
 60	        let h2 = self.lin2.forward(&h1)?.relu()?;
 61	        let out = self.lin3.forward(&h2)?;
 62	
 63	        let scores = out.to_vec2::<f32>()?;
 64	        Ok(scores.into_iter().map(|row| row[0]).collect())
 65	    }
 66	}
 67	
 68	/// Compute 16-dim feature vector for a candidate 2-opt move.
 69	fn move_features_2opt(
 70	    route: &[usize],
 71	    i: usize,
 72	    j: usize,
 73	    matrix: &DistMatrix,
 74	    route_total_dist: f64,
 75	) -> [f32; MOVE_FEATURE_DIM] {
 76	    let n = route.len();
 77	    let a = route[i - 1];
 78	    let b = route[i];
 79	    let c = route[j];
 80	    let d = route[(j + 1) % n];
 81	
 82	    let d_ab = matrix_get_dist(matrix, a, b);
 83	    let d_cd = matrix_get_dist(matrix, c, d);
 84	    let d_ac = matrix_get_dist(matrix, a, c);
 85	    let d_bd = matrix_get_dist(matrix, b, d);
 86	
 87	    let delta = (d_ac + d_bd) - (d_ab + d_cd);
 88	
 89	    let avg_edge = if n > 1 {
 90	        route_total_dist / (n - 1) as f64
 91	    } else {
 92	        1.0
 93	    };
 94	    let avg_edge = avg_edge.max(1e-6);
 95	
 96	    let seg_len = (i..=j)
 97	        .map(|k| matrix_get_dist(matrix, route[k], route[(k + 1) % n]))
 98	        .sum::<f64>();
 99	
100	    let seg_stops = (j - i + 1) as f64;
101	    let route_len = n as f64;
102	
103	    [
104	        d_ab as f32,
105	        d_cd as f32,
106	        d_ac as f32,
107	        d_bd as f32,
108	        delta as f32,
109	        (d_ab / avg_edge) as f32,
110	        (d_cd / avg_edge) as f32,
111	        (d_ac / avg_edge) as f32,
112	        (d_bd / avg_edge) as f32,
113	        seg_len as f32,
114	        (seg_len / route_total_dist.max(1e-6)) as f32,
115	        seg_stops as f32,
116	        (seg_stops / route_len) as f32,
117	        (i as f64 / route_len) as f32,
118	        (j as f64 / route_len) as f32,
119	        if delta < -1e-6 { 1.0 } else { 0.0 },
120	    ]
121	}
122	
123	/// Compute 16-dim feature vector for a candidate Or-Opt move (relocation).
124	fn move_features_oropt(
125	    _matrix: &DistMatrix,
126	    remove_gain: f64,
127	    insert_cost: f64,
128	    chain_len: usize,
129	    is_rev: bool,
130	    route_len: usize,
131	) -> [f32; MOVE_FEATURE_DIM] {
132	    let delta = insert_cost - remove_gain;
133	    [
134	        remove_gain as f32,
135	        insert_cost as f32,
136	        delta as f32,
137	        chain_len as f32,
138	        if is_rev { 1.0 } else { 0.0 },
139	        (delta / (remove_gain.abs() + 1e-6)) as f32,
140	        (chain_len as f32 / route_len as f32) as f32,
141	        0.0,
142	        0.0,
143	        0.0,
144	        0.0,
145	        0.0,
146	        0.0,
147	        0.0,
148	        0.0, // padding to 16
149	        if delta < -1e-6 { 1.0 } else { 0.0 },
150	    ]
151	}
